import csv

with open('/tmp/weo_apr2025.xls', 'r', encoding='utf-16-le') as f:
    reader = csv.reader(f, delimiter='\t')
    headers = next(reader)

    # Find year columns
    year_cols = {}
    for i, h in enumerate(headers):
        if h.isdigit() and 2020 <= int(h) <= 2030:
            year_cols[h] = i
    print("Year columns:", year_cols)

    # Find Georgia data (ISO code GEO)
    georgia_data = []
    for row in reader:
        if len(row) > 1 and row[1] == 'GEO':
            subject_code = row[2] if len(row) > 2 else ""
            subject_desc = row[4] if len(row) > 4 else ""
            units = row[6] if len(row) > 6 else ""
            scale = row[7] if len(row) > 7 else ""

            # Get values for our years
            values = {}
            for year, col_idx in year_cols.items():
                if col_idx < len(row):
                    values[year] = row[col_idx]

            georgia_data.append({
                'code': subject_code,
                'desc': subject_desc,
                'units': units,
                'scale': scale,
                'values': values
            })

    # Filter for key indicators
    key_indicators = ['NGDP', 'NGDP_R', 'NGDP_RPCH', 'NGDP_D', 'NGDPD', 'PCPI', 'PCPIPCH']
    for data in georgia_data:
        if data['code'] in key_indicators:
            print(f"\n{data['code']}: {data['desc']}")
            print(f"  Units: {data['units']}, Scale: {data['scale']}")
            print(f"  Values: {data['values']}")
